using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace Dafeiyu {
internal sealed class GeneratedImageGroupCard:Grid {
readonly PetWindow pet;readonly Window host;readonly GeneratedImageGroupState state=new GeneratedImageGroupState();readonly ContentControl main=new ContentControl();readonly StackPanel rail=new StackPanel();readonly ScrollViewer scroll;ChatMessage message;string signature;bool attached;
internal string SelectedId{get{return state.SelectedId;}}
internal GeneratedImageGroupCard(PetWindow owner,Window window){pet=owner;host=window;Name="GeneratedImageGroupCard";HorizontalAlignment=HorizontalAlignment.Stretch;ColumnDefinitions.Add(new ColumnDefinition());ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});RowDefinitions.Add(new RowDefinition());RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});scroll=new ScrollViewer{Content=rail,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,MaxHeight=360};Children.Add(main);Children.Add(scroll);SizeChanged+=delegate{Layout();};Loaded+=delegate{attached=true;pet.ImageTasks.Changed+=Changed;Refresh();};Unloaded+=delegate{attached=false;pet.ImageTasks.Changed-=Changed;};}
void Changed(ImageGenerationTaskSnapshot task){if(message!=null&&(message.ImageGenerationTaskIds??new List<string>()).Contains(task.Id))Dispatcher.BeginInvoke(new Action(delegate{if(attached)Refresh();}));}
internal void Update(ChatMessage value){message=value;Refresh();}
void Refresh(){if(message==null)return;state.Update(message.ImageGenerationTaskIds,message.GeneratedImages??new List<GeneratedImage>(),id=>{var saved=pet.ImageStore.FindByJobId(id);var task=pet.ImageTasks.Get(id);return saved??(task==null||String.IsNullOrEmpty(task.ResultImageId)?null:pet.ImageStore.Get(task.ResultImageId));});var parts=new List<string>();foreach(var id in state.Keys){var image=state.ImageFor(id);var task=pet.ImageTasks.Get(id);parts.Add(id+":"+(image==null?"":image.Id)+":"+(task==null?"":task.State.ToString()));}string next=String.Join("|",parts);if(next==signature)return;signature=next;Rebuild();}
void Rebuild(){rail.Children.Clear();foreach(var key in state.Keys){string id=key;var asset=state.ImageFor(id);FrameworkElement content=Ui.Text((rail.Children.Count+1).ToString(),12,Ui.Muted);if(asset!=null)try{int w,h;bool limited;content=new Image{Source=ChatImagePreview.DecodeGeneratedImage(pet.ImageStore.Read(asset.Id),80,out w,out h,out limited),Stretch=Stretch.UniformToFill};}catch(Exception error){if(!(error is System.IO.IOException||error is UnauthorizedAccessException||error is ArgumentException||error is NotSupportedException||error is FormatException))throw;}var button=new Button{Name="GeneratedImageGroupSlot",Tag=id,Width=64,Height=64,Margin=new Thickness(4),Padding=new Thickness(2),Background=ThemeManager.Surface,Content=content,BorderThickness=new Thickness(id==state.SelectedId?2:1),BorderBrush=id==state.SelectedId?Ui.Blue:Ui.Line};button.ToolTip=asset!=null?"图片 "+(rail.Children.Count+1):ImageGenerationMotion.Label(pet.ImageTasks.Get(id));button.Click+=delegate{state.Select(id);ShowSelected();foreach(Button item in rail.Children){item.BorderThickness=new Thickness((string)item.Tag==id?2:1);item.BorderBrush=(string)item.Tag==id?Ui.Blue:Ui.Line;}};rail.Children.Add(button);}ShowSelected();Visibility=state.Keys.Count>0?Visibility.Visible:Visibility.Collapsed;Layout();}
void ShowSelected(){var asset=state.SelectedImage;main.Content=asset!=null?(FrameworkElement)new GeneratedImageCard(pet,host,asset,selected=>{var chat=host as ChatWindow;if(chat!=null)chat.ShowImagesPage(selected);else pet.OpenImageWorkspace(selected);}):state.SelectedId!=null?(pet.ImageTasks.Get(state.SelectedId)!=null?(FrameworkElement)ImageGenerationPendingCard.Create(pet,host,state.SelectedId):Ui.Text("图片记录不可用",12,Ui.Muted)):null;}
void Layout(){bool wide=ActualWidth>=480;Grid.SetColumn(scroll,wide?1:0);Grid.SetRow(scroll,wide?0:1);rail.Orientation=wide?Orientation.Vertical:Orientation.Horizontal;scroll.Visibility=state.Keys.Count>1?Visibility.Visible:Visibility.Collapsed;scroll.HorizontalScrollBarVisibility=wide?ScrollBarVisibility.Disabled:ScrollBarVisibility.Auto;scroll.VerticalScrollBarVisibility=wide?ScrollBarVisibility.Auto:ScrollBarVisibility.Disabled;}
}}
